\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{calc,positioning,decorations.pathreplacing,arrows.meta,shapes.geometric}
\pagestyle{empty}

% ═══════════════════════════════════════════════════════════
% DARK-MODE DEVELOPER-TOOL COLOR SCHEME
% ═══════════════════════════════════════════════════════════
\definecolor{darkbg}{HTML}{0F172A}        % Page background (deep navy)
\definecolor{cardbg}{HTML}{1E293B}        % Card background (dark slate)
\definecolor{cardbgblue}{HTML}{162544}     % Blue-tinted card bg
\definecolor{cardbgteal}{HTML}{132A33}     % Teal-tinted card bg
\definecolor{cardbgamber}{HTML}{2A2214}    % Amber-tinted card bg
\definecolor{titlebg}{HTML}{0A0F1E}       % Title bar bg (very dark)
\definecolor{electricblue}{HTML}{3B82F6}   % Primary accent
\definecolor{teal}{HTML}{06B6D4}           % Secondary accent
\definecolor{amber}{HTML}{F59E0B}          % Warning / caution accent
\definecolor{green}{HTML}{10B981}          % Success accent
\definecolor{lighttext}{HTML}{E2E8F0}      % Primary text (light gray)
\definecolor{dimtext}{HTML}{94A3B8}        % Secondary text (muted)
\definecolor{statbg}{HTML}{172033}         % Stat banner bg
\definecolor{gridline}{HTML}{1E3A5F}       % Subtle grid lines
\definecolor{era1}{HTML}{6366F1}           % 2017-2019 (indigo)
\definecolor{era2}{HTML}{8B5CF6}           % 2020 (violet)
\definecolor{era3}{HTML}{3B82F6}           % 2021 (blue)
\definecolor{era4}{HTML}{06B6D4}           % 2022 (teal)
\definecolor{era5}{HTML}{10B981}           % 2023 (green)
\definecolor{era6}{HTML}{F59E0B}           % 2024 (amber)
\definecolor{era7}{HTML}{EF4444}           % 2025 (red)
\definecolor{era8}{HTML}{EC4899}           % 2026 (pink)

\pagecolor{darkbg}
\color{lighttext}

% ═══════════════════════════════════════════════════════════
% LIST STYLING
% ═══════════════════════════════════════════════════════════
\setlist[itemize]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{electricblue}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{teal}\bfseries\arabic*.}}

% ═══════════════════════════════════════════════════════════
% CARD STYLES (Dark-Mode Left Accent Stripe)
% ═══════════════════════════════════════════════════════════
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgblue,
    borderline west={5pt}{0pt}{electricblue},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{electricblue},
    coltitle=electricblue, colbacktitle=cardbgblue!80!darkbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1pt, titlerule style={electricblue!40},
    valign=top, drop shadow={opacity=0.25,shadow xshift=2pt,shadow yshift=-2pt},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgteal,
    borderline west={5pt}{0pt}{teal},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{teal},
    coltitle=teal, colbacktitle=cardbgteal!80!darkbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1pt, titlerule style={teal!40},
    valign=top, drop shadow={opacity=0.25,shadow xshift=2pt,shadow yshift=-2pt},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgamber,
    borderline west={5pt}{0pt}{amber},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=cardbgamber!80!darkbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1pt, titlerule style={amber!40},
    valign=top, drop shadow={opacity=0.25,shadow xshift=2pt,shadow yshift=-2pt},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=electricblue!20!darkbg,
    borderline west={6pt}{0pt}{electricblue},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=electricblue!60!darkbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1pt, titlerule style={electricblue!60},
    valign=top, drop shadow={opacity=0.3,shadow xshift=2pt,shadow yshift=-2pt},
  },
}

% ═══════════════════════════════════════════════════════════
% CUSTOM COMMANDS
% ═══════════════════════════════════════════════════════════
\newcommand{\bodytext}{\fontsize{28}{36}\selectfont\color{lighttext}}
\newcommand{\dimlabel}{\fontsize{22}{28}\selectfont\color{dimtext}}
\newcommand{\ttdata}{\fontsize{26}{32}\selectfont\ttfamily\color{teal}}
\newcommand{\subheader}[2]{\fontsize{30}{36}\selectfont\bfseries\color{#1}#2}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════════════════════
% TITLE BAR (rows 1-3, span=3)
% ═══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=titlebg, colframe=titlebg, colupper=lighttext,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=6pt,
  halign=center, valign=center,
  borderline south={4pt}{0pt}{electricblue},
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{62}{74}\selectfont\bfseries\color{electricblue} JS Framework Benchmark}\\[8pt]
  {\fontsize{38}{46}\selectfont\color{lighttext} 5 Years of Browser Performance Testing}\\[6pt]
  {\fontsize{22}{28}\selectfont\color{dimtext} Chrome 55 $\to$ 146 \quad$\cdot$\quad 60+ Official Runs \quad$\cdot$\quad 2017--2026 \quad$\cdot$\quad \ttfamily github.com/krausest/js-framework-benchmark}
}

% ═══════════════════════════════════════════════════════════
% STATS BANNER (rows 3-5, span=3) — Hero Numbers
% ═══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=statbg, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  valign=center,
  borderline south={2pt}{0pt}{gridline},
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{electricblue!40}{electricblue!12!darkbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{56}{68}\selectfont\bfseries\ttfamily\color{electricblue} 60+}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{dimtext} Official Benchmark Runs}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{teal!40}{teal!12!darkbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{56}{68}\selectfont\bfseries\ttfamily\color{teal} 55--146}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{dimtext} Chrome Versions Spanned}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{amber!40}{amber!12!darkbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{56}{68}\selectfont\bfseries\ttfamily\color{amber} Ch.\,118}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{dimtext} Methodology Overhaul}\vspace{6pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════════
% TIMELINE HERO (rows 5-11, span=3) — The Centerpiece
% ═══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=6pt, bottom=4pt,
  borderline west={5pt}{0pt}{electricblue},
  valign=top,
]{name=timeline, column=1, span=3, between=row5 and row11}{
  \subheader{electricblue}{Benchmark Timeline: Chrome 55 $\to$ 146}\\[6pt]
  \begin{tikzpicture}[
    x=0.56mm,
    y=1cm,
    every node/.style={font=\fontsize{18}{22}\selectfont\color{lighttext}},
    yearnode/.style={font=\fontsize{20}{24}\selectfont\bfseries, text=lighttext},
    runnode/.style={font=\fontsize{15}{18}\selectfont\color{dimtext}},
    milestonenode/.style={font=\fontsize{16}{20}\selectfont\bfseries, text=amber},
    dot/.style={circle, fill=#1, minimum size=8pt, inner sep=0pt},
    ambermark/.style={regular polygon, regular polygon sides=3, fill=amber, minimum size=12pt, inner sep=0pt},
  ]
    % Main timeline bar
    \fill[gridline, rounded corners=3pt] (0,0) rectangle (540,0.6);
    % Gradient overlay segments by era
    \fill[era1, opacity=0.5, rounded corners=2pt] (0,0.05) rectangle (62,0.55);
    \fill[era2, opacity=0.5, rounded corners=2pt] (62,0.05) rectangle (130,0.55);
    \fill[era3, opacity=0.5, rounded corners=2pt] (130,0.05) rectangle (210,0.55);
    \fill[era4, opacity=0.5, rounded corners=2pt] (210,0.05) rectangle (300,0.55);
    \fill[era5, opacity=0.6, rounded corners=2pt] (300,0.05) rectangle (380,0.55);
    \fill[era6, opacity=0.5, rounded corners=2pt] (380,0.05) rectangle (445,0.55);
    \fill[era7, opacity=0.5, rounded corners=2pt] (445,0.05) rectangle (515,0.55);
    \fill[era8, opacity=0.5, rounded corners=2pt] (515,0.05) rectangle (540,0.55);

    % Chrome version markers (selected)
    \node[dot=era1]   at (5,1.1) {};
    \node[runnode, above] at (5,1.4) {Ch.\,55};
    \node[dot=era1]   at (22,1.1) {};
    \node[dot=era1]   at (42,1.1) {};
    \node[dot=era1]   at (62,1.1) {};
    \node[runnode, above] at (62,1.4) {Ch.\,69};

    \node[dot=era2]   at (82,1.1) {};
    \node[dot=era2]   at (100,1.1) {};
    \node[dot=era2]   at (118,1.1) {};
    \node[dot=era2]   at (130,1.1) {};

    \node[dot=era3]   at (142,1.1) {};
    \node[dot=era3]   at (160,1.1) {};
    \node[dot=era3]   at (178,1.1) {};
    \node[dot=era3]   at (196,1.1) {};
    \node[dot=era3]   at (210,1.1) {};

    \node[dot=era4]   at (228,1.1) {};
    \node[dot=era4]   at (248,1.1) {};
    \node[dot=era4]   at (268,1.1) {};
    \node[dot=era4]   at (288,1.1) {};
    \node[dot=era4]   at (300,1.1) {};

    % Chrome 118 MILESTONE — amber warning marker
    \node[ambermark] at (330,1.1) {};
    \node[milestonenode, above] at (330,1.7) {Ch.\,118};
    \draw[amber, thick, dashed] (330,0.8) -- (330,0.6);

    \node[dot=era5]   at (310,1.1) {};
    \node[dot=era5]   at (350,1.1) {};
    \node[dot=era5]   at (370,1.1) {};
    \node[dot=era5]   at (380,1.1) {};

    \node[dot=era6]   at (395,1.1) {};
    \node[dot=era6]   at (412,1.1) {};
    \node[dot=era6]   at (428,1.1) {};
    \node[dot=era6]   at (445,1.1) {};

    \node[dot=era7]   at (460,1.1) {};
    \node[dot=era7]   at (478,1.1) {};
    \node[dot=era7]   at (495,1.1) {};
    \node[dot=era7]   at (510,1.1) {};

    \node[dot=era8]   at (520,1.1) {};
    \node[dot=era8]   at (530,1.1) {};
    \node[dot=era8]   at (540,1.1) {};
    \node[runnode, above] at (540,1.4) {Ch.\,146};

    % Year labels below the bar
    \node[yearnode] at (31,-0.5) {2017--19};
    \node[yearnode] at (96,-0.5) {2020};
    \node[yearnode] at (170,-0.5) {2021};
    \node[yearnode] at (255,-0.5) {2022};
    \node[yearnode] at (340,-0.5) {2023};
    \node[yearnode] at (412,-0.5) {2024};
    \node[yearnode] at (480,-0.5) {2025};
    \node[yearnode] at (530,-0.5) {2026};

    % Run count badges below years
    \node[runnode] at (31,-1.1) {4 runs};
    \node[runnode] at (96,-1.1) {5 runs};
    \node[runnode] at (170,-1.1) {9 runs};
    \node[runnode] at (255,-1.1) {13 runs};
    \node[runnode] at (340,-1.1) {12 runs};
    \node[runnode] at (412,-1.1) {12 runs};
    \node[runnode] at (480,-1.1) {12 runs};
    \node[runnode] at (530,-1.1) {3 runs};

    % Chrome 118 caution callout box
    \node[
      draw=amber, fill=amber!15!darkbg, rounded corners=4pt,
      text width=160mm, align=left,
      font=\fontsize{18}{22}\selectfont\color{lighttext},
      inner sep=8pt,
    ] at (330,-2.8) {
      {\fontsize{20}{24}\selectfont\bfseries\color{amber} $\blacktriangle$ Caution: Chrome 118 Methodology Change}\\[3pt]
      \color{dimtext} Overall score switched from arithmetic to {\color{teal}\bfseries weighted geometric mean}.\\
      \color{dimtext} CPU throttling factors recalibrated. Cross-version comparisons are {\color{amber}\bfseries unreliable}.
    };
    \draw[amber, thick, -Stealth] (330,0) -- (330,-1.5);

    % Migration note
    \node[
      draw=era2, fill=era2!12!darkbg, rounded corners=3pt,
      text width=80mm, align=center,
      font=\fontsize{16}{20}\selectfont\color{dimtext},
      inner sep=6pt,
    ] at (96,-2.4) {
      Migrated to\\GitHub Pages
    };

    % Windows run callout
    \node[
      draw=era4, fill=era4!12!darkbg, rounded corners=3pt,
      text width=80mm, align=center,
      font=\fontsize{16}{20}\selectfont\color{dimtext},
      inner sep=6pt,
    ] at (255,-2.0) {
      Windows runs:\\Ch.\,104 (2022)
    };
    \draw[era4, thin] (255,-0.6) -- (255,-1.3);

    % Keyed-only callout
    \node[
      draw=era7, fill=era7!12!darkbg, rounded corners=3pt,
      text width=80mm, align=center,
      font=\fontsize{16}{20}\selectfont\color{dimtext},
      inner sep=6pt,
    ] at (480,-2.0) {
      Keyed-only runs\\on odd Chrome v.
    };

  \end{tikzpicture}
}

% ═══════════════════════════════════════════════════════════
% OVERVIEW (col 1, rows 11-15)
% ═══════════════════════════════════════════════════════════
\posterbox[bluecard, title={What Is the JS Framework Benchmark?}
]{name=overview, column=1, between=row11 and row15}{
  \bodytext
  \begin{itemize}[itemsep=10pt]
    \item Open-source benchmark by {\color{electricblue}\bfseries Stefan Krause}
    \item Measures {\color{teal}\bfseries real DOM operations} in Chrome
    \item Create 1K rows, updates, swap, remove, startup
    \item Controlled {\color{amber}\bfseries CPU throttling} for consistency
    \item Tracks keyed {\&} non-keyed implementations
  \end{itemize}
  \vspace{4pt}
  \colorbox{electricblue!18!darkbg}{\parbox{0.92\linewidth}{%
    \fontsize{22}{28}\selectfont\color{lighttext}\bfseries
    The de facto standard for JS framework performance comparison
  }}
}

% ═══════════════════════════════════════════════════════════
% METHODOLOGY MILESTONES (col 2, rows 11-15)
% ═══════════════════════════════════════════════════════════
\posterbox[ambercard, title={Methodology Milestones}
]{name=methodology, column=2, between=row11 and row15}{
  \bodytext
  \colorbox{amber!20!darkbg}{\parbox{0.92\linewidth}{%
    \fontsize{22}{28}\selectfont\color{amber}\bfseries Chrome 118 (2023) --- Major Overhaul}\\[3pt]
    \fontsize{20}{26}\selectfont\color{lighttext}
    $\bullet$ Arithmetic $\to$ {\color{teal}\bfseries weighted geometric mean}\\
    \fontsize{20}{26}\selectfont\color{lighttext}
    $\bullet$ CPU throttling recalibrated\\
    \fontsize{20}{26}\selectfont\color{lighttext}
    $\bullet$ Timing \& driver refinements
  }}\\[8pt]
  \colorbox{era7!18!darkbg}{\parbox{0.92\linewidth}{%
    \fontsize{22}{28}\selectfont\color{era7}\bfseries Chrome 139+ (2025--26)}\\[3pt]
    \fontsize{20}{26}\selectfont\color{lighttext}
    $\bullet$ Odd Chrome versions: {\color{electricblue}\bfseries keyed only}\\
    \fontsize{20}{26}\selectfont\color{lighttext}
    $\bullet$ Even versions: full keyed + non-keyed
  }}\\[8pt]
  \colorbox{red!15!darkbg}{\parbox{0.92\linewidth}{%
    \fontsize{20}{26}\selectfont\color{red!80!white}\bfseries
    $\blacktriangle$ Cross-version comparisons are unreliable
  }}
}

% ═══════════════════════════════════════════════════════════
% PLATFORM & COVERAGE (col 3, rows 11-15)
% ═══════════════════════════════════════════════════════════
\posterbox[tealcard, title={Platform \& Coverage}
]{name=coverage, column=3, between=row11 and row15}{
  \bodytext
  \colorbox{teal!18!darkbg}{\parbox{0.92\linewidth}{%
    \fontsize{22}{28}\selectfont\color{teal}\bfseries 95\%+ runs on macOS}\\[2pt]
    \fontsize{20}{26}\selectfont\color{dimtext}
    Only 2 Windows runs: Ch.\,104, Ch.\,121
  }}\\[6pt]
