═\n% PLATFORM & COVERAGE (col 3, rows 11-15)\n% ═══════════════════════════════════════════════════════════\n\\posterbox[tealcard, title={Platform \\& Coverage}\n]{name=coverage, column=3, between=row11 and row15}{\n  \\bodytext\n  \\colorbox{teal!18!darkbg}{\\parbox{0.92\\linewidth}{%\n    \\fontsize{22}{28}\\selectfont\\color{teal}\\bfseries 95\\%+ runs on macOS}\\\\[2pt]\n    \\fontsize{20}{26}\\selectfont\\color{dimtext}\n    Only 2 Windows runs: Ch.\\,104, Ch.\\,121\n  }}\\\\[6pt]\n  {\\fontsize{20}{24}\\selectfont\\color{lighttext}%\n  \\renewcommand{\\arraystretch}{1.5}%\n  \\begin{tabular}{@{}lcc@{}}\n    \\rowcolor{teal!15!darkbg}\n    {\\color{teal}\\bfseries Year} & {\\color{teal}\\bfseries Runs} & {\\color{teal}\\bfseries Chrome} \\\\\n    \\rowcolor{cardbg} 2017--19 & 4 & 55--69 \\\\\n    \\rowcolor{teal!8!darkbg} 2020 & 5 & 83--87 \\\\\n    \\rowcolor{cardbg} 2021 & 9 & 88--96 \\\\\n    \\rowcolor{teal!8!darkbg} 2022 & 13 & 97--108 \\\\\n    \\rowcolor{cardbg} 2023 & 12 & 109--120 \\\\\n    \\rowcolor{teal!8!darkbg} 2024 & 12 & 121--131 \\\\\n    \\rowcolor{amber!10!darkbg} 2025 & 12 & 132--143 \\\\\n    \\rowcolor{cardbg} 2026 & 3 & 144--146 \\\\\n  \\end{tabular}}\n}\n\n% ═══════════════════════════════════════════════════════════\n% KEY TAKEAWAYS (span=3, rows 16-20)\n% ═══════════════════════════════════════════════════════════\n\\posterbox[highlightcard, title={Key Takeaways for Developers}\n]{name=takeaways, column=1, span=3, between=row16 and row20}{\n  \\bodytext\n  \\begin{minipage}[t]{0.32\\linewidth}\n    \\colorbox{electricblue!20!darkbg}{\\parbox{0.92\\linewidth}{%\n      \\fontsize{24}{30}\\selectfont\\color{electricblue}\\bfseries 1.\\ Compare within same Chrome version}\\\\[3pt]\n      \\fontsize{20}{26}\\selectfont\\color{lighttext}\n      Methodology and throttling differ across releases. Never mix results from different Chrome versions.\n    }}\n  \\end{minipage}\\hfill\n  \\begin{minipage}[t]{0.32\\linewidth}\n    \\colorbox{electricblue!20!darkbg}{\\parbox{0.92\\linewidth}{%\n      \\fontsize{24}{30}\\selectfont\\color{electricblue}\\bfseries 2.\\ Consult latest run (Ch.\\,146)}\\\\[3pt]\n      \\fontsize{20}{26}\\selectfont\\color{lighttext}\n      Current standings reflect the most up-to-date methodology and framework versions.\n    }}\n  \\end{minipage}\\hfill\n  \\begin{minipage}[t]{0.32\\linewidth}\n    \\colorbox{electricblue!20!darkbg}{\\parbox{0.92\\linewidth}{%\n      \\fontsize{24}{30}\\selectfont\\color{electricblue}\\bfseries 3.\\ Keyed vs non-keyed modes}\\\\[3pt]\n      \\fontsize{20}{26}\\selectfont\\color{lighttext}\n      Odd Chrome runs test keyed frameworks only. Even runs include both keyed and non-keyed.\n    }}\n  \\end{minipage}\n  \\vspace{8pt}\n\n  \\centering\n  \\colorbox{green!20!darkbg}{\\parbox{0.96\\linewidth}{%\n    \\centering\\vspace{4pt}\n    {\\fontsize{22}{28}\\selectfont\\color{green}\\bfseries\n    60+ data points over 8 years --- the longest-running, most comprehensive JS framework performance tracker available}\\\\[2pt]\n    {\\fontsize{18}{22}\\selectfont\\color{dimtext}\n    Weighted geometric mean (since Chrome 118) gives a more balanced overall score than the previous arithmetic approach}\n    \\vspace{4pt}\n  }}\n}\n\n\\end{tcbposter}\n\\end{document}\n", "numLines": 426, "startLine": 1, "totalLines": 426}}

