\definecolor{green}{HTML}{10B981}          % Success accent
\definecolor{lighttext}{HTML}{E2E8F0}      % Primary text (light gray)
\definecolor{dimtext}{HTML}{94A3B8}        % Secondary text (muted)
\definecolor{statbg}{HTML}{172033}         % Stat banner bg
\definecolor{gridline}{HTML}{1E3A5F}       % Subtle grid lines
