Windows: Ch.\\,104};\n\n    % Keyed-only note\n    \\node[\n      draw=era7, fill=era7!12!darkbg, rounded corners=3pt,\n      font=\\fontsize{15}{19}\\selectfont\\color{dimtext},\n      inner sep=5pt, align=center,\n    ] at (480,-1.8) {Keyed-only odd Ch.\\,v.};\n\n  \\end{tikzpicture}\n}\n\n% ═══════════════════════════════════════════════════════════\n% OVERVIEW (col 1, rows 11-15)\n% ═══════════════════════════════════════════════════════════\n\\posterbox[bluecard, title={What Is the JS Framework Benchmark?}\n]{name=overview, column=1, between=row11 and row15}{\n  \\bodytext\n  \\begin{itemize}[itemsep=8pt]\n    \\item Open-source by {\\color{electricblue}\\bfseries Stefan Krause}\n    \\item Measures {\\color{teal}\\bfseries real DOM operations} in Chrome\n    \\item 1K rows, updates, swap, remove, startup\n    \\item Controlled {\\color{amber}\\bfseries CPU throttling}\n    \\item Tracks keyed and non-keyed\n  \\end{itemize}\n  \\vspace{4pt}\n  \\noindent\\fcolorbox{electricblue!30}{electricblue!18!darkbg}{\\parbox{0.88\\linewidth}{%\n    \\fontsize{20}{26}\\selectfont\\color{lighttext}\\bfseries\n    The de facto standard for JS framework performance comparison\n  }}\n}\n\n% ═══════════════════════════════════════════════════════════\n% METHODOLOGY MILESTONES (col 2, rows 11-15)\n% ═══════════════════════════════════════════════════════════\n\\posterbox[ambercard, title={Methodology Milestones}\n]{name=methodology, column=2, between=row11 and row15}{\n  \\bodytext\n  \\noindent\\fcolorbox{amber!30}{amber!20!darkbg}{\\parbox{0.88\\linewidth}{%\n    \\fontsize{20}{26}\\selectfont\\color{amber}\\bfseries Chrome 118 (2023) --- Major Overhaul}%\n  }\\par\\vspace{4pt}\n  \\smalltext\n  $\\bullet$ Arithmetic $\\to$ {\\color{teal}\\bfseries weighted geometric mean}\\par\\vspace{2pt}\n  $\\bullet$ CPU throttling recalibrated\\par\\vspace{2pt}\n  $\\bullet$ Timing and driver refinements\\par\\vspace{6pt}\n  \\noindent\\fcolorbox{era7!30}{era7!18!darkbg}{\\parbox{0.88\\linewidth}{%\n    \\fontsize{20}{26}\\selectfont\\color{era7}\\bfseries Chrome 139+ (2025-26)}%\n  }\\par\\vspace{4pt}\n  \\smalltext\n  $\\bullet$ Odd Chrome v.: {\\color{electricblue}\\bfseries keyed only}\\par\\vspace{2pt}\n  $\\bullet$ Even Chrome v.: keyed + non-keyed\\par\\vspace{6pt}\n  \\noindent\\fcolorbox{red!30}{red!15!darkbg}{\\parbox{0.88\\linewidth}{%\n    \\fontsize{19}{25}\\selectfont\\color{red!80!white}\\bfseries\n    Cross-version comparisons are unreliable\n  }}\n}\n\n% ═══════════════════════════════════════════════════════════\n% PLATFORM & COVERAGE (col 3, rows 11-15)\n% ═══════════════════════════════════════════════════════════\n\\posterbox[tealcard, title={Platform and Coverage}\n]{name=coverage, column=3, between=row11 and row15}{\n  \\bodytext\n  \\noindent\\fcolorbox{teal!30}{teal!18!darkbg}{\\parbox{0.88\\linewidth}{%\n    \\fontsize{20}{26}\\selectfont\\color{teal}\\bfseries 95\\%+ runs on macOS}%\n  }\\par\\vspace{2pt}\n  \\dimtext Only 2 Windows runs: Ch.\\,104, Ch.\\,121\\par\\vspace{6pt}\n  {\\fontsize{18}{22}\\selectfont\\color{lighttext}%\n  \\renewcommand{\\arraystretch}{1.4}%\n  \\begin{tabular}{@{}lcc@{}}\n    \\rowcolor{teal!15!darkbg}\n    {\\color{teal}\\bfseries Year} & {\\color{teal}\\bfseries Runs} & {\\color{teal}\\bfseries Chrome} \\\\\n    \\rowcolor{cardbg} 2017-19 & 4 & 55-69 \\\\\n    \\rowcolor{teal!8!darkbg} 2020 & 5 & 83-87 \\\\\n    \\rowcolor{cardbg} 2021 & 9 & 88-96 \\\\\n    \\rowcolor{teal!8!darkbg} 2022 & 13 & 97-108 \\\\\n    \\rowcolor{cardbg} 2023 & 12 & 109-120 \\\\\n    \\rowcolor{teal!8!darkbg} 2024 & 12 & 121-131 \\\\\n    \\rowcolor{amber!10!darkbg} 2025 & 12 & 132-143 \\\\\n    \\rowcolor{cardbg} 2026 & 3 & 144-146 \\\\\n  \\end{tabular}}\n}\n\n% ═══════════════════════════════════════════════════════════\n% KEY TAKEAWAYS (span=3, rows 16-20)\n% ═══════════════════════════════════════════════════════════\n\\posterbox[highlightcard, title={Key Takeaways for Developers}\n]{name=takeaways, column=1, span=3, between=row16 and row20}{\n  \\bodytext\n  \\begin{minipage}[t]{0.31\\linewidth}\n    \\fcolorbox{electricblue!30}{electricblue!20!darkbg}{\\parbox{0.86\\linewidth}{%\n      \\fontsize{22}{28}\\selectfont\\color{electricblue}\\bfseries 1. Compare within same Chrome version}%\n    }\\par\\vspace{3pt}\n    \\dimtext Methodology and throttling differ across releases. Never mix results from different versions.\n  \\end{minipage}\\hfill\n  \\begin{minipage}[t]{0.31\\linewidth}\n    \\fcolorbox{electricblue!30}{electricblue!20!darkbg}{\\parbox{0.86\\linewidth}{%\n      \\fontsize{22}{28}\\selectfont\\color{electricblue}\\bfseries 2. Consult latest run (Ch.\\,146)}%\n    }\\par\\vspace{3pt}\n    \\dimtext Current standings reflect the most up-to-date methodology and framework versions.\n  \\end{minipage}\\hfill\n  \\begin{minipage}[t]{0.31\\linewidth}\n    \\fcolorbox{electricblue!30}{electricblue!20!darkbg}{\\parbox{0.86\\linewidth}{%\n      \\fontsize{22}{28}\\selectfont\\color{electricblue}\\bfseries 3. Keyed vs non-keyed modes}%\n    }\\par\\vspace{3pt}\n    \\dimtext Odd Chrome runs: keyed only. Even runs: both keyed and non-keyed.\n  \\end{minipage}\n  \\vspace{10pt}\n\n  \\centering\n  \\fcolorbox{green!30}{green!20!darkbg}{\\parbox{0.94\\linewidth}{%\n    \\centering\\vspace{4pt}\n    {\\fontsize{20}{26}\\selectfont\\color{green}\\bfseries\n    60+ data points over 8 years --- the longest-running, most comprehensive JS framework performance tracker available}\\par\\vspace{2pt}\n    {\\fontsize{16}{20}\\selectfont\\color{dimtext}\n    Weighted geometric mean (since Chrome 118) gives a more balanced overall score}\n    \\vspace{4pt}\n  }}\n}\n\n\\end{tcbposter}\n\\end{document}\n", "numLines": 409, "startLine": 1, "totalLines": 409}}

