\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgblue,
    borderline west={5pt}{0pt}{electricblue},
    left=14pt, right=12pt, top=6pt, bottom=6pt,
