  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{amber!40}{amber!12!darkbg}{\parbox{0.84\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{48}{60}\selectfont\bfseries\ttfamily\color{amber} Ch.\,118}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{dimtext} Methodology Overhaul}\vspace{5pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════════
% TIMELINE HERO (rows 5-10, span=3) — The Centerpiece
% ═══════════════════════════════════════════════════════════
