]{name=timeline, column=1, span=3, between=row5 and row10}{
  {\fontsize{28}{36}\selectfont\bfseries\color{electricblue} Benchmark Timeline: Chrome 55 -> 146}\\[4pt]
  \begin{tikzpicture}[
    x=0.53mm,
    y=1cm,
    every node/.style={font=\fontsize{16}{20}\selectfont\color{lighttext}},
    yearnode/.style={font=\fontsize{17}{21}\selectfont\bfseries, text=lighttext},
    runnode/.style={font=\fontsize{13}{17}\selectfont, text=dimtext},
    milestonenode/.style={font=\fontsize{17}{21}\selectfont\bfseries, text=amber},
    dot/.style={circle, fill=#1, minimum size=8pt, inner sep=0pt},
  ]
    % Subtle dot grid background
    \foreach \i in {0,20,...,540} {
