    \fill[era8, opacity=0.55, rounded corners=2pt] (515,0.06) rectangle (538,0.54);

    % Chrome version dots above the bar
    \node[dot=era1] at (5,1.0) {};
    \node[runnode, above] at (5,1.3) {Ch.\,55};
    \node[dot=era1] at (22,1.0) {};
    \node[dot=era1] at (42,1.0) {};
    \node[dot=era1] at (62,1.0) {};
    \node[runnode, above] at (62,1.3) {Ch.\,69};

    \node[dot=era2] at (82,1.0) {};
    \node[dot=era2] at (100,1.0) {};
    \node[dot=era2] at (118,1.0) {};
    \node[dot=era2] at (130,1.0) {};

    \node[dot=era3] at (142,1.0) {};
    \node[dot=era3] at (160,1.0) {};
    \node[dot=era3] at (178,1.0) {};
    \node[dot=era3] at (196,1.0) {};
    \node[dot=era3] at (210,1.0) {};

    \node[dot=era4] at (228,1.0) {};
    \node[dot=era4] at (248,1.0) {};
    \node[dot=era4] at (268,1.0) {};
