    \node[dot=era6] at (395,1.0) {};
    \node[dot=era6] at (412,1.0) {};
    \node[dot=era6] at (428,1.0) {};
    \node[dot=era6] at (445,1.0) {};

    \node[dot=era7] at (460,1.0) {};
    \node[dot=era7] at (478,1.0) {};
    \node[dot=era7] at (495,1.0) {};
    \node[dot=era7] at (510,1.0) {};

    \node[dot=era8] at (520,1.0) {};
    \node[dot=era8] at (530,1.0) {};
    \node[dot=era8] at (540,1.0) {};
    \node[runnode, above] at (540,1.3) {Ch.\,146};

    % ── CHROME 118 CAUTION (prominent) ──
    \draw[amber, line width=2pt, dashed] (330,0.75) -- (330,-0.5);
    \node[regular polygon, regular polygon sides=3, fill=amber,
      minimum size=14pt, inner sep=0pt] at (330,1.0) {};
    \node[milestonenode] at (330,1.7) {Ch.\,118};

    % Year labels below
    \node[yearnode] at (31,-0.6) {2017-19};
    \node[yearnode] at (96,-0.6) {2020};
    \node[yearnode] at (170,-0.6) {2021};
    \node[yearnode] at (255,-0.6) {2022};
    \node[yearnode] at (340,-0.6) {2023};
    \node[yearnode] at (412,-0.6) {2024};
    \node[yearnode] at (480,-0.6) {2025};
    \node[yearnode] at (530,-0.6) {2026};

    % Run counts below years
    \node[runnode] at (31,-1.1) {4 runs};
    \node[runnode] at (96,-1.1) {5 runs};
    \node[runnode] at (170,-1.1) {9 runs};
    \node[runnode] at (255,-1.1) {13 runs};
