    % ── RUNS-PER-YEAR BAR CHART below timeline ──
    \draw[gridline!40, thin] (0,-1.8) -- (540,-1.8);
    % Bars (max=13, scale: 1 run = 4mm height, bars 40mm wide)
    \fill[era1, opacity=0.7, rounded corners=1pt] (16,-1.8) rectangle (46,-3.4);
    \node[font=\fontsize{12}{15}\selectfont, text=era1] at (31,-3.6) {4};
    \fill[era2, opacity=0.7, rounded corners=1pt] (81,-1.8) rectangle (111,-3.8);
