    \node[font=\fontsize{12}{15}\selectfont, text=era7] at (480,-6.8) {12};
    \fill[era8, opacity=0.7, rounded corners=1pt] (515,-1.8) rectangle (545,-3.0);
    \node[font=\fontsize{12}{15}\selectfont, text=era8] at (530,-3.2) {3};

