      {\color{teal}\bfseries weighted geometric mean}.\\
      CPU throttling factors recalibrated. Measurement instrumentation refined.\\[2pt]
      {\color{amber!90!white}\bfseries
        Comparisons across Chrome versions are not reliable.}
    };
    \draw[amber, thick, -{Stealth[length=8pt]}] (330,-0.5) -- (280,-4.8);

    % Small annotation callouts
    \node[
      draw=era2!60, fill=era2!10!darkbg, rounded corners=2pt,
