% ═══════════════════════════════════════════════════════════
% OVERVIEW (col 1, rows 10-15)
% ═══════════════════════════════════════════════════════════
\posterbox[bluecard, title={What Is the JS Framework Benchmark?}
]{name=overview, column=1, between=row10 and row15}{
  \bodytext
  \begin{itemize}[itemsep=6pt]
    \item Open-source by {\color{electricblue}\bfseries Stefan Krause}
    \item Measures {\color{teal}\bfseries real DOM operations} in Chrome
    \item 1K rows, updates, swap, remove, startup time
    \item Controlled {\color{amber}\bfseries CPU throttling}
    \item Tracks keyed and non-keyed implementations
  \end{itemize}
  \vspace{3pt}
  \noindent\fcolorbox{electricblue!30}{electricblue!20!darkbg}{\parbox{0.86\linewidth}{%
    \fontsize{18}{24}\selectfont\color{lighttext}\bfseries
    The de facto standard for JS framework performance comparison
  }}
}

% ═══════════════════════════════════════════════════════════
% METHODOLOGY MILESTONES (col 2, rows 10-15)
% ═══════════════════════════════════════════════════════════
\posterbox[ambercard, title={Methodology Milestones}
]{name=methodology, column=2, between=row10 and row15}{
  \bodytext
  \noindent\fcolorbox{amber!30}{amber!22!darkbg}{\parbox{0.86\linewidth}{%
    \fontsize{19}{25}\selectfont\color{amber}\bfseries Chrome 118 (2023) --- Major Overhaul}%
  }\par\vspace{3pt}
  \smalltext
  $\bullet$ Arithmetic $\to$ {\color{teal}\bfseries weighted geometric mean}\par\vspace{2pt}
  $\bullet$ CPU throttling recalibrated\par\vspace{2pt}
  $\bullet$ Timing and driver refinements\par\vspace{5pt}
  \noindent\fcolorbox{era7!30}{era7!18!darkbg}{\parbox{0.86\linewidth}{%
    \fontsize{19}{25}\selectfont\color{era7}\bfseries Chrome 139+ (2025-26)}%
  }\par\vspace{3pt}
  \smalltext
  $\bullet$ Odd Chrome v.: {\color{electricblue}\bfseries keyed only}\par\vspace{2pt}
  $\bullet$ Even Chrome v.: keyed + non-keyed\par\vspace{5pt}
  \noindent\fcolorbox{red!30}{red!18!darkbg}{\parbox{0.86\linewidth}{%
    \fontsize{18}{24}\selectfont\color{red!80!white}\bfseries
    $\blacktriangle$ Cross-version comparisons are unreliable
  }}
}

% ═══════════════════════════════════════════════════════════
% PLATFORM & COVERAGE (col 3, rows 10-15)
% ═══════════════════════════════════════════════════════════
\posterbox[tealcard, title={Platform and Coverage}
]{name=coverage, column=3, between=row10 and row15}{
  \bodytext
  \noindent\fcolorbox{teal!30}{teal!18!darkbg}{\parbox{0.86\linewidth}{%
    \fontsize{19}{25}\selectfont\color{teal}\bfseries 95\%+ runs on macOS}%
  }\par\vspace{2pt}
  \dimtext Only 2 Windows runs: Ch.\,104, Ch.\,121\par\vspace{4pt}
  {\fontsize{17}{21}\selectfont\color{lighttext}%
  \renewcommand{\arraystretch}{1.35}%
  \begin{tabular}{@{}lcc@{}}
    \rowcolor{teal!15!darkbg}
    {\color{teal}\bfseries Year} & {\color{teal}\bfseries Runs} & {\color{teal}\bfseries Chrome} \\
    \rowcolor{cardbg} 2017-19 & 4 & 55-69 \\
    \rowcolor{teal!8!darkbg} 2020 & 5 & 83-87 \\
    \rowcolor{cardbg} 2021 & 9 & 88-96 \\
    \rowcolor{teal!8!darkbg} 2022 & 13 & 97-108 \\
    \rowcolor{cardbg} 2023 & 12 & 109-120 \\
    \rowcolor{teal!8!darkbg} 2024 & 12 & 121-131 \\
    \rowcolor{amber!10!darkbg} 2025 & 12 & 132-143 \\
    \rowcolor{cardbg} 2026 & 3 & 144-146 \\
  \end{tabular}}
}

% ═══════════════════════════════════════════════════════════
% KEY TAKEAWAYS (span=3, rows 15-20)
% ═══════════════════════════════════════════════════════════
\posterbox[highlightcard, title={Key Takeaways for Developers}
]{name=takeaways, column=1, span=3, between=row15 and row20}{
  \bodytext
  \begin{minipage}[t]{0.31\linewidth}
    \fcolorbox{electricblue!30}{electricblue!22!darkbg}{\parbox{0.84\linewidth}{%
      \fontsize{20}{26}\selectfont\color{electricblue}\bfseries 1.\ Compare within same Chrome version}%
    }\par\vspace{3pt}
    \dimtext Methodology and throttling differ across releases. Never mix results from different Chrome versions.
  \end{minipage}\hfill
  \begin{minipage}[t]{0.31\linewidth}
    \fcolorbox{electricblue!30}{electricblue!22!darkbg}{\parbox{0.84\linewidth}{%
      \fontsize{20}{26}\selectfont\color{electricblue}\bfseries 2.\ Consult latest run (Ch.\,146)}%
    }\par\vspace{3pt}
    \dimtext Current standings reflect the most up-to-date methodology and framework versions.
  \end{minipage}\hfill
  \begin{minipage}[t]{0.31\linewidth}
    \fcolorbox{electricblue!30}{electricblue!22!darkbg}{\parbox{0.84\linewidth}{%
      \fontsize{20}{26}\selectfont\color{electricblue}\bfseries 3.\ Keyed vs non-keyed modes}%
    }\par\vspace{3pt}
    \dimtext Odd Chrome runs: keyed frameworks only. Even runs: both keyed and non-keyed.
  \end{minipage}
  \vspace{8pt}

  \centering
  \fcolorbox{green!30}{green!22!darkbg}{\parbox{0.92\linewidth}{%
    \centering\vspace{3pt}
    {\fontsize{19}{25}\selectfont\color{green}\bfseries
    60+ data points over 8 years --- the longest-running, most comprehensive JS framework performance tracker available}\par\vspace{2pt}
    {\fontsize{15}{19}\selectfont\color{dimtext}
    Weighted geometric mean (since Chrome 118) gives a more balanced overall score}
    \vspace{3pt}
  }}
}

